#!/usr/bin/env node
// Task 5 CLI: build blind packets from a fixture file. The CLI does not run
// any production external calls; it consumes a fixture that bundles a frozen
// protocol, the registry, generated bytes, and verified render evidence, then
// delegates to the build capability.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { loadRegistry } from "./lib/registry.mjs";
import { createBuildAuthority } from "./lib/packet-build-authority.mjs";
import { buildBlindPackets } from "./lib/blind.mjs";

const command = process.argv[2] ?? "preflight";
const root = resolve(new URL("../../../", import.meta.url).pathname);

if (command === "preflight") {
  const registry = loadRegistry(root);
  if (registry.scenarios.length !== 12 || registry.anchors.length !== 4) {
    throw new Error("preflight|registry|corpus|size");
  }
  console.log("effectiveness-v2 packet-builder preflight passed; build capability available");
  process.exit(0);
}
if (command === "build") {
  const fixturePath = process.argv[3];
  const secretPath = process.argv[4];
  if (!fixturePath || !secretPath) {
    throw new Error("usage: build-packets.mjs build <fixture.json> <secret-path>");
  }
  const fixture = JSON.parse(readFileSync(fixturePath, "utf8"));
  const privateStateRef = {
    domain: fixture.domain ?? "effectiveness-v2-production",
    secretPath: resolve(secretPath),
    commitment_sha256: fixture.protocol.randomization_commitment_sha256
  };
  const capability = createBuildAuthority(privateStateRef);
  const built = buildBlindPackets({ ...fixture, registry: loadRegistry(root), buildCapability: capability });
  console.log(JSON.stringify({
    packet_set_sha256: built.packet_set_sha256,
    map_commitment: built.map_commitment,
    packet_count: built.packets.length,
    anchor_count: built.anchor_packets.length,
    adapter_sha256: createHash("sha256").update(readFileSync(new URL("./lib/packet-build-authority.mjs", import.meta.url))).digest("hex")
  }));
  process.exit(0);
}
throw new Error("usage: build-packets.mjs preflight|build <fixture.json> <secret-path>");
